from reports.format import format_invoice, format_quote

CUSTOMER = {"name": "Ada Lovelace", "street": "1 Main St", "zip": "1011", "city": "Amsterdam"}


def test_invoice():
    text = format_invoice(CUSTOMER, [("Pen", 1.5), ("Pad", 2.0)])
    assert text.splitlines()[0] == "ADA LOVELACE"
    assert text.splitlines()[-1] == "TOTAL                   3.50"


def test_quote():
    text = format_quote(CUSTOMER, [("Pen", 1.5)])
    assert "Valid for 30 days" in text

