from reports.format import format_invoice, format_quote

CUSTOMER = {"name": "Ada", "street": "S", "zip": "1", "city": "C", "country": "de"}


def test_exact_layout():
    assert format_invoice(CUSTOMER, [("Pen", 1.5)]) == (
        "ADA\nS\n1 C\nDE\n\nPen                     1.50\nTOTAL                   1.50"
    )
    assert format_quote(CUSTOMER, [("Pen", 1.5)], valid_days=7) == (
        "ADA\nS\n1 C\nDE\n\nValid for 7 days\nPen                     1.50"
    )
